980b50ddda036e2587c1eb9f9152716edd"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"things"}}},"attribute_id":{"$ref":{"table":"attributes","where":{"slug":"trade-off-summary"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:cb4eaf6690f985d8a9050db280f6c7960fc7c4d39b6a05dc7c526a1ac0d5409e"}}}}]},{"table":"product_anchor_evidence","operation":"upsert","conflictColumns":["product_id","anchor_id","relationship_type","claim_evidence_id"],"rows":[{"product_id":{"$ref":{"table":"products","where":{"slug":"2do"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"todoist"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:623b14fc7f6813557057f59c3ae72896a23944a45a40e0db6323e54b13806c3e"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"2do"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"todoist"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:b7d797be22b39b6c5e1c25a9af2b6d73eb5e3cb882334a64404365ab0203a198"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"omnifocus"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"todoist"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:261bdded44aa0e67ad69d85678eeb3b25898d69e257e6e9177fa27bec03523d9"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"omnifocus"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"todoist"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:eeae3cdb4619d1eed535bb9ecfb3365b32cf7d43e5a42830315dddd0fe2f0e70"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"things"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"todoist"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:1b36634ba6d9c0350b13495cb06c355a9027b44fccf617f4eef5b8c0587b86fb"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"things"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"todoist"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:ed4d26d65b3fdc9d96438a85cc71a25e9963ce7d26effd91f05531272fd1ff80"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"omnifocus"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"todoist"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:556e0de5ba0895f11710eefaa589411df901c742491fd4203e5779b85d5b002d"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"things"}}},"anchor_id":{"$ref":{"table":"anchors","where":{"slug":"todoist"}}},"relationship_type":"alternative","claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:f42f04357d8dc6fe84da8a4cb8772c6b4f7f458ac89d1ac3f074528a12f9bdb8"}}}}]},{"table":"product_problem_evidence","operation":"upsert","conflictColumns":["product_id","problem_id","claim_evidence_id"],"rows":[]},{"table":"product_audience_evidence","operation":"upsert","conflictColumns":["product_id","audience_id","claim_evidence_id"],"rows":[{"product_id":{"$ref":{"table":"products","where":{"slug":"2do"}}},"audience_id":{"$ref":{"table":"audiences","where":{"slug":"productivity-users"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:fb1ee9d93f300a1342d74cc60ecadd74f99cc156eda66540e45be7afd423170a"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"omnifocus"}}},"audience_id":{"$ref":{"table":"audiences","where":{"slug":"personal-task-planners"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:92c5f670d226adcd51b64beaeaddac8782fab5d857076068a5340e932fd5d7d8"}}}},{"product_id":{"$ref":{"table":"products","where":{"slug":"things"}}},"audience_id":{"$ref":{"table":"audiences","where":{"slug":"personal-task-planners"}}},"claim_evidence_id":{"$ref":{"table":"claim_evidence","where":{"seed_key":"seed-claim:b3a3047630db25dc2a6d0eb7dd65cc7c633c9daef2173d15283fbf49d09f7d48"}}}}]},{"table":"escape_routes","operation":"upsert","conflictColumns":["slug"],"rows":[]},{"table":"escape_route_products","operation":"upsert","conflictColumns":["escape_route_id","product_id"],"rows":[]}],"route":{"slug":"todoist-alternatives-with-a-one-time-purchase","name":"Todoist Alternatives With a One-Time Purchase","description":"Personal task capture and project organization with paid native editions that can be bought once. Compare Things 3 platform purchases, OmniFocus 4 native perpetual licenses and the 2Do Mac direct-purchase license. Platforms, mobile purchases, optional Web subscriptions and future update entitlements differ. This is a bounded personal-workflow comparison; it does not guarantee team, platform or complete Todoist parity.","anchor_id":{"$ref":{"table":"anchors","where":{"slug":"todoist"}}},"last_verified_at":"2026-10-07T00:00:00Z"},"members":[{"productSlug":"2do","position":1,"noveltyScore":0,"editorialNote":"Personal task capture and project organization only. Edition: 2Do Mac direct-purchase license. Mobile purchases and future update entitlement are separate; Todoist sync is not proof of independent replacement. No guarantee of team, platform or complete Todoist parity."},{"productSlug":"omnifocus","position":2,"noveltyScore":0,"editorialNote":"Personal task capture and project organization only. Edition: OmniFocus 4 native Standard/Pro perpetual license. Native Apple edition only; Web subscription and future major upgrades are separate. No guarantee of team, platform or complete Todoist parity."},{"productSlug":"things","position":3,"noveltyScore":0,"editorialNote":"Personal task capture and project organization only. Edition: Things 3 platform purchases. Apple-only applications; platforms sold separately; real-time shared lists unsupported. No guarantee of team, platform or complete Todoist parity."}]}$pr59_data$::jsonb;
 tbl jsonb; item jsonb; wanted jsonb; prop record; ref_where record;
 ref_id uuid; matched boolean; actual_count integer; expected_count integer;
 target_id uuid; route_id uuid; product_slug text; page jsonb;
BEGIN
 SET LOCAL lock_timeout='10s';
 PERFORM pg_advisory_xact_lock(7232003);
 LOCK TABLE software_discovery.evidence_sources, software_discovery.anchors, software_discovery.attributes, software_discovery.problems, software_discovery.audiences, software_discovery.products, software_discovery.product_attributes, software_discovery.product_anchors, software_discovery.product_problems, software_discovery.product_audiences, software_discovery.claim_evidence, software_discovery.product_attribute_evidence, software_discovery.product_anchor_evidence, software_discovery.product_problem_evidence, software_discovery.product_audience_evidence, software_discovery.escape_routes, software_discovery.escape_route_products IN SHARE ROW EXCLUSIVE MODE;
 IF (SELECT count(*) FROM software_discovery.products WHERE slug IN ('2do','omnifocus','things') AND status IN ('draft','published'))<>3 THEN RAISE EXCEPTION 'PR5.9 target lifecycle mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM software_discovery.escape_route_products m JOIN software_discovery.escape_routes r ON r.id=m.escape_route_id JOIN software_discovery.products p ON p.id=m.product_id WHERE p.slug IN ('2do','omnifocus','things') AND r.slug<>'todoist-alternatives-with-a-one-time-purchase' AND r.status='published' AND r.editorially_approved) THEN RAISE EXCEPTION 'PR5.9 other approved route exposure requires review'; END IF;
 FOR tbl IN SELECT value FROM jsonb_array_elements(payload->'tables') LOOP
  FOR item IN SELECT value FROM jsonb_array_elements(tbl->'rows') LOOP
   wanted=item;
   FOR prop IN SELECT key,value FROM jsonb_each(item) LOOP
    IF prop.value ? '$ref' THEN
     SELECT key,value INTO STRICT ref_where FROM jsonb_each(prop.value->'$ref'->'where');
     ref_id=NULL;
     EXECUTE format('SELECT id FROM software_discovery.%I WHERE %I=$1',prop.value->'$ref'->>'table',ref_where.key) INTO ref_id USING ref_where.value #>> '{}';
     IF ref_id IS NULL THEN RAISE EXCEPTION 'PR5.9 required reference missing'; END IF;
     wanted=jsonb_set(wanted,ARRAY[prop.key],to_jsonb(ref_id));
    END IF;
   END LOOP;
   IF tbl->>'table'='products' THEN wanted=wanted-'status'; END IF;
   EXECUTE format('SELECT EXISTS(SELECT 1 FROM software_discovery.%I c WHERE NOT EXISTS(SELECT 1 FROM jsonb_object_keys($1) k WHERE to_jsonb(c)->k IS DISTINCT FROM to_jsonb(jsonb_populate_record(NULL::software_discovery.%I,$1))->k))',tbl->>'table',tbl->>'table') INTO matched USING wanted;
   IF NOT matched THEN RAISE EXCEPTION 'PR5.9 review mismatch: %',tbl->>'table'; END IF;
  END LOOP;
  IF left(tbl->>'table',8)='product_' THEN
   FOREACH product_slug IN ARRAY ARRAY['2do','omnifocus','things'] LOOP
    SELECT id INTO STRICT target_id FROM software_discovery.products WHERE slug=product_slug;
    SELECT count(*) INTO expected_count FROM jsonb_array_elements(tbl->'rows') r WHERE r->'product_id'->'$ref'->'where'->>'slug'=product_slug;
    EXECUTE format('SELECT count(*) FROM software_discovery.%I WHERE product_id=$1',tbl->>'table') INTO actual_count USING target_id;
    IF actual_count<>expected_count THEN RAISE EXCEPTION 'PR5.9 relationship/evidence set changed: %/%',product_slug,tbl->>'table'; END IF;
   END LOOP;
  END IF;
 END LOOP;
 SELECT id INTO STRICT ref_id FROM software_discovery.anchors WHERE slug='todoist';
 wanted=jsonb_set(payload->'route',ARRAY['anchor_id'],to_jsonb(ref_id));
 SELECT id INTO route_id FROM software_discovery.escape_routes WHERE slug='todoist-alternatives-with-a-one-time-purchase';
 IF route_id IS NOT NULL THEN
  SELECT EXISTS(SELECT 1 FROM software_discovery.escape_routes c WHERE c.id=route_id AND ((status='draft' AND NOT editorially_approved) OR (status='published' AND editorially_approved)) AND NOT EXISTS(SELECT 1 FROM jsonb_object_keys(wanted) k WHERE to_jsonb(c)->k IS DISTINCT FROM to_jsonb(jsonb_populate_record(NULL::software_discovery.escape_routes,wanted))->k)) INTO matched;
  IF NOT matched THEN RAISE EXCEPTION 'PR5.9 route metadata/approval mismatch'; END IF;
  SELECT count(*) INTO actual_count FROM software_discovery.escape_route_products WHERE escape_route_id=route_id;
  IF actual_count NOT IN (0,3) THEN RAISE EXCEPTION 'PR5.9 route membership drift'; END IF;
  IF actual_count=3 THEN
   FOR item IN SELECT value FROM jsonb_array_elements(payload->'members') LOOP
    SELECT id INTO STRICT target_id FROM software_discovery.products WHERE slug=item->>'productSlug';
    IF NOT EXISTS(SELECT 1 FROM software_discovery.escape_route_products m WHERE escape_route_id=route_id AND product_id=target_id AND position=(item->>'position')::integer AND novelty_score=0 AND relevance_score IS NULL AND constraint_fit_score IS NULL AND quality_score IS NULL AND editorial_note=item->>'editorialNote') THEN RAISE EXCEPTION 'PR5.9 member data mismatch'; END IF;
   END LOOP;
  END IF;
 ELSE
  INSERT INTO software_discovery.escape_routes(slug,name,description,anchor_id,last_verified_at) SELECT slug,name,description,anchor_id,last_verified_at FROM jsonb_populate_record(NULL::software_discovery.escape_routes,wanted) RETURNING id INTO route_id;
 END IF;
 UPDATE software_discovery.products SET status='published',updated_at=now() WHERE slug IN ('2do','omnifocus','things') AND status='draft';
 FOR item IN SELECT value FROM jsonb_array_elements(payload->'members') LOOP
  SELECT id INTO STRICT target_id FROM software_discovery.products WHERE slug=item->>'productSlug';
  INSERT INTO software_discovery.escape_route_products(escape_route_id,product_id,position,novelty_score,editorial_note) VALUES(route_id,target_id,(item->>'position')::integer,0,item->>'editorialNote') ON CONFLICT(escape_route_id,product_id) DO NOTHING;
 END LOOP;
 UPDATE software_discovery.escape_routes SET status='published',editorially_approved=true,updated_at=now() WHERE id=route_id AND status='draft' AND NOT editorially_approved;
 FOREACH product_slug IN ARRAY ARRAY['2do','omnifocus','things'] LOOP
  page=software_discovery.product_discovery_page(product_slug);
  IF page IS NULL OR page->>'status'<>'published' OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(page->'anchors') a WHERE a->>'slug'='todoist' AND a->>'scope'='personal-task-project-organization' AND a->>'verificationStatus'='verified') THEN RAISE EXCEPTION 'PR5.9 public projection failed'; END IF;
 END LOOP;
 -- Approved apply persists atomically.
EXCEPTION WHEN SQLSTATE 'ZP509' THEN RAISE NOTICE 'PR5.9 rehearsal rolled back; no publication persisted';
END $pr59$;
